#!/usr/bin/env node
/**
 * Build the vendored chromium-bidi mapper bundle from the pinned manifest.
 *
 * Usage:
 *   node scripts/mapper/build.mjs           # write src/lib/bidi/vendor/*
 *   node scripts/mapper/build.mjs --check   # rebuild in memory, exit 1 if the
 *                                           # committed files differ
 *
 * Every generated byte comes from the integrity-pinned inputs in
 * chromium-bidi-mapper.manifest.json, so the committed bundle can be proven
 * byte-for-byte in CI. Never hand-edit the generated files.
 */

import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import {
  formatManifest,
  manifestPath,
  readManifest,
  sha256,
  vendorDir,
  withToolchain,
} from './lib.mjs';

const SRC = 'chromium-bidi/out/Default/gen/src';

/** What the bundle exports, and where each export lives upstream. */
export const ENTRY_EXPORTS = {
  BidiServer: `${SRC}/bidiMapper/BidiMapper.js`,
  MapperCdpConnection: `${SRC}/cdp/CdpConnection.js`,
};

/** Upstream declarations craftdriver's hand-written .d.ts mirrors. */
const API_DECLARATIONS = [
  'bidiMapper/BidiServer.d.ts',
  'bidiMapper/BidiTransport.d.ts',
  'cdp/CdpConnection.d.ts',
  'utils/transport.d.ts',
];

/** Inputs that must never reach the bundle (zod and the types-only protocol). */
const FORBIDDEN_INPUTS = [/node_modules\/zod\//, /devtools-protocol/, /\/protocol-parser\//];

export const SIZE_BUDGET_BYTES = 1024 * 1024;

export const FILES = {
  bundle: 'chromium-bidi-mapper.js',
  api: 'chromium-bidi-mapper.api.txt',
  manifest: 'chromium-bidi-mapper.manifest.json',
};

/** `node_modules/@scope/name/...` or `node_modules/name/...` → package name. */
export function packageOf(inputPath) {
  const m = inputPath.match(/node_modules\/((?:@[^/]+\/)?[^/]+)\//);
  return m ? m[1] : null;
}

/**
 * The build's safety checks. Pure, so tests can feed fake metafiles.
 * Returns a list of failure messages (empty when the bundle is acceptable).
 */
export function checkGuards({ metafile, code, exportNames, manifest }) {
  const failures = [];
  const inputs = Object.keys(metafile.inputs);

  const unexpected = [
    ...new Set(inputs.map(packageOf).filter((p) => p && !manifest.bundledPackages.includes(p))),
  ];
  if (unexpected.length) {
    failures.push(
      `new transitive runtime dependency: ${unexpected.join(', ')}. ` +
        'Review its licence and add it to manifest.bundledPackages deliberately.'
    );
  }

  const forbidden = inputs.filter((i) => FORBIDDEN_INPUTS.some((re) => re.test(i)));
  if (forbidden.length) {
    failures.push(`forbidden module in the bundle:\n  ${forbidden.join('\n  ')}`);
  }

  const bytes = Buffer.byteLength(code);
  if (bytes > SIZE_BUDGET_BYTES) {
    failures.push(`bundle is ${bytes} bytes, over the ${SIZE_BUDGET_BYTES}-byte budget`);
  }

  const missing = manifest.entryExports.filter((name) => !exportNames.includes(name));
  if (missing.length) failures.push(`entry export missing: ${missing.join(', ')}`);

  return failures;
}

/** Strip comments and collapse whitespace so only the shape of the API counts. */
export function normalizeDeclarations(text) {
  return text
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/(^|[^:])\/\/.*$/gm, '$1')
    .split('\n')
    .map((l) => l.trim().replace(/\s+/g, ' '))
    .filter(Boolean)
    .join('\n');
}

function header(manifest) {
  const { chromiumBidi, mitt, esbuild } = manifest;
  return [
    '/*!',
    ' * GENERATED by scripts/mapper/build.mjs from the pinned inputs in',
    ' * chromium-bidi-mapper.manifest.json. Do not edit; regenerate with',
    ' * `npm run mapper:build`.',
    ' *',
    ` * chromium-bidi ${chromiumBidi.version} (Apache-2.0, see LICENSE.chromium-bidi)`,
    ` * mitt ${mitt.version} (MIT, see LICENSE.mitt)`,
    ` * bundled with esbuild ${esbuild.version}`,
    ' */',
    '',
  ].join('\n');
}

/**
 * Build everything in memory. Returns `{ files, manifest, report }`, where
 * `files` maps vendor-dir file names to their exact contents.
 */
export async function buildMapper(manifest) {
  return withToolchain(manifest, async (dir) => {
    const { build } = await import(
      pathToFileURL(path.join(dir, 'node_modules', 'esbuild', 'lib', 'main.js')).href
    );
    const entry = Object.entries(ENTRY_EXPORTS)
      .map(([name, from]) => `export { ${name} } from '${from}';`)
      .join('\n');
    fs.writeFileSync(path.join(dir, 'entry.mjs'), entry + '\n');

    const result = await build({
      entryPoints: ['entry.mjs'],
      absWorkingDir: dir,
      bundle: true,
      format: 'esm',
      platform: 'node',
      target: 'node22',
      minify: false,
      legalComments: 'eof',
      metafile: true,
      write: false,
      logLevel: 'silent',
    });
    const code = result.outputFiles[0].text;
    const output = Object.values(result.metafile.outputs)[0];

    const failures = checkGuards({
      metafile: result.metafile,
      code,
      exportNames: output.exports,
      manifest,
    });
    if (failures.length) {
      const err = new Error(`Mapper bundle guards failed:\n- ${failures.join('\n- ')}`);
      err.guardFailures = failures;
      throw err;
    }

    const declDir = path.join(dir, 'node_modules', SRC);
    const api =
      API_DECLARATIONS.map(
        (rel) =>
          `// ${rel}\n${normalizeDeclarations(fs.readFileSync(path.join(declDir, rel), 'utf8'))}`
      ).join('\n\n') + '\n';

    const bundle = header(manifest) + code;
    const next = {
      ...manifest,
      output: { bytes: Buffer.byteLength(bundle), sha256: sha256(bundle) },
      apiFingerprint: sha256(api),
    };

    const files = {
      [FILES.bundle]: bundle,
      [FILES.api]: api,
      [FILES.manifest]: formatManifest(next),
    };
    for (const pkg of manifest.bundledPackages) {
      files[`LICENSE.${pkg}`] = fs.readFileSync(
        path.join(dir, 'node_modules', pkg, 'LICENSE'),
        'utf8'
      );
    }

    const inputs = Object.keys(result.metafile.inputs);
    const report = {
      modules: inputs.filter((i) => packageOf(i)).length,
      packages: [...new Set(inputs.map(packageOf).filter(Boolean))].sort(),
      bytes: next.output.bytes,
    };
    return { files, manifest: next, report };
  });
}

/** Lines that differ between two texts: the first mismatch, for a readable error. */
function firstDifference(a, b) {
  const al = a.split('\n');
  const bl = b.split('\n');
  for (let i = 0; i < Math.max(al.length, bl.length); i++) {
    if (al[i] !== bl[i]) {
      return `line ${i + 1}:\n  committed: ${al[i] ?? '<eof>'}\n  rebuilt:   ${bl[i] ?? '<eof>'}`;
    }
  }
  return 'contents differ';
}

/** Compare a build against the vendor dir. Returns mismatch messages. */
export function compareWithVendor(files, dir = vendorDir) {
  const problems = [];
  for (const [name, content] of Object.entries(files)) {
    const file = path.join(dir, name);
    if (!fs.existsSync(file)) {
      problems.push(`${name}: missing from ${path.relative(process.cwd(), dir)}`);
      continue;
    }
    const committed = fs.readFileSync(file, 'utf8');
    if (committed !== content) problems.push(`${name}: ${firstDifference(committed, content)}`);
  }
  return problems;
}

export function writeVendor(files, dir = vendorDir) {
  fs.mkdirSync(dir, { recursive: true });
  for (const [name, content] of Object.entries(files)) {
    fs.writeFileSync(path.join(dir, name), content);
  }
}

async function main() {
  const check = process.argv.includes('--check');
  const manifest = readManifest(manifestPath);
  const { files, report } = await buildMapper(manifest);

  if (check) {
    const problems = compareWithVendor(files);
    if (problems.length) {
      console.error(
        `Vendored mapper bundle is out of date or was edited by hand:\n${problems.join('\n')}\n` +
          'Regenerate with `npm run mapper:build`.'
      );
      process.exit(1);
    }
    console.log(`mapper:check OK (chromium-bidi ${manifest.chromiumBidi.version})`);
    return;
  }

  writeVendor(files);
  console.log(
    `Built chromium-bidi ${manifest.chromiumBidi.version}: ${report.bytes} bytes, ` +
      `${report.modules} modules from ${report.packages.join(', ')}`
  );
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((err) => {
    console.error(err.message);
    process.exit(err.guardFailures ? 20 : 1);
  });
}
